UPDATE ifj_job
SET current_definition_id = #{definitionId},
    current_revision = #{nextRevision},
    name = #{name},
    timeout = #{timeout},
    enabled = #{enabled},
    description = #{description},
    update_time = #{updateTime}
WHERE id = #{jobId}
  AND current_definition_id = #{expectedDefinitionId}
  AND current_revision = #{expectedRevision}
  AND retired = 0FALSE
  AND retired_time IS NULL

UPDATE ifj_job
SET current_definition_id = #{definitionId},
    current_revision = #{nextRevision},
    name = #{name},
    timeout = #{timeout},
    enabled = #{enabled},
    description = #{description},
    update_time = #{updateTime}
WHERE id = #{jobId}
  AND current_definition_id = #{expectedDefinitionId}
  AND current_revision = #{expectedRevision}
  AND retired = 0
  AND retired_time IS NULL

UPDATE ifj_job
SET retired = TRUE,
    retired_time = #{retiredTime},
    update_time = #{retiredTime}
WHERE id = #{jobId}
  AND retired = FALSE
  AND retired_time IS NULL
  AND current_definition_id <=> #{expectedDefinitionId}
  AND current_revision <=> #{expectedRevision}

UPDATE ifj_job
SET retired = TRUE,
    retired_time = #{retiredTime},
    update_time = #{retiredTime}
WHERE id = #{jobId}
  AND retired = FALSE
  AND retired_time IS NULL
  AND current_definition_id IS NOT DISTINCT FROM #{expectedDefinitionId}
  AND current_revision IS NOT DISTINCT FROM #{expectedRevision}

UPDATE ifj_job
SET retired = TRUE,
    retired_time = #{retiredTime},
    update_time = #{retiredTime}
WHERE id = #{jobId}
  AND retired = FALSE
  AND retired_time IS NULL
  AND current_definition_id IS #{expectedDefinitionId}
  AND current_revision IS #{expectedRevision}
